import pandas as pd,numpy as np
from pymatgen.core import Structure
from pymatgen.symmetry.analyzer import SpacegroupAnalyzer
def scan(s,label):
    out=[]
    for sp in [0.01,0.05,0.1,0.3,0.5,0.8]:
        try: sga=SpacegroupAnalyzer(s,symprec=sp); out.append('%s:%s'%(sp,sga.get_space_group_symbol()))
        except Exception as e: out.append('%s:err'%sp)
    print(label.ljust(14),' '.join(out))
t=pd.read_csv('cdft_piezo_d_eg_train.csv'); p=pd.read_csv('cdft_piezo_pool.csv').set_index('candidate_id')
for i,r in t.iterrows():
    if r.formula in ['RbPbBr3','TlHgF3','TiPbO3','RbCaCl3','TlCdF3','SrHfO3','LiGeBO4','Na3SbS4']:
        scan(Structure.from_str(r.poscar,fmt='poscar'),r.formula+' d=%.0f'%r.d_ij)
print()
for c in ['c011','c092','c005','c066','c067','c072','c060','c010','c029','c051','c090','c041']:
    scan(Structure.from_str(p.loc[c,'poscar'],fmt='poscar'),c+' '+p.loc[c,'formula'])
"

